// auth.middleware.js
const jwt = require('jsonwebtoken');
const config = require('../config');

const authenticate = (req, res, next) => {
  try {
    const authHeader = req.headers.authorization;

    if (!authHeader) {
      return res.status(401).json({
        status: 'error',
        message: 'Authentication required',
        code: 'MISSING_TOKEN'
      });
    }

    if (!authHeader.startsWith('Bearer ')) {
      return res.status(401).json({
        status: 'error',
        message: 'Invalid token format',
        code: 'INVALID_TOKEN_FORMAT'
      });
    }

    const token = authHeader.split(' ')[1];

    const decoded = jwt.verify(token, config.jwt.secret, {
      algorithms: ['HS256']
    });

    // Attach user to request
    req.user = decoded;
    req.userId = decoded.userId;

    next();
  } catch (err) {
    if (err.name === 'JsonWebTokenError') {
      return res.status(401).json({
        status: 'error',
        message: 'Invalid token',
        code: 'INVALID_TOKEN'
      });
    }

    if (err.name === 'TokenExpiredError') {
      return res.status(401).json({
        status: 'error',
        message: 'Token expired',
        code: 'TOKEN_EXPIRED'
      });
    }

    next(err);
  }
};

const authorize = (...roles) => {
  return (req, res, next) => {
    if (!req.user) {
      return res.status(401).json({ error: 'Unauthorized' });
    }

    if (!roles.includes(req.user.role)) {
      return res.status(403).json({
        status: 'error',
        message: 'Insufficient permissions',
        code: 'FORBIDDEN'
      });
    }

    next();
  };
};

module.exports = { authenticate, authorize };

// error.middleware.js
const logger = require('../utils/logger');

class AppError extends Error {
  constructor(message, statusCode, code = 'INTERNAL_ERROR') {
    super(message);
    this.statusCode = statusCode;
    this.code = code;
    this.isOperational = true;
    Error.captureStackTrace(this, this.constructor);
  }
}

const errorHandler = (err, req, res, next) => {
  // Log error
  logger.error('Error occurred:', {
    message: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method,
    ip: req.ip,
    userId: req.userId,
    timestamp: new Date().toISOString()
  });

  // Determine status code
  const statusCode = err.statusCode || 500;
  const code = err.code || 'INTERNAL_ERROR';
  const message = statusCode === 500 && !err.isOperational
    ? 'Internal server error'
    : err.message;

  // Build response
  const response = {
    status: 'error',
    code,
    message,
    path: req.path,
    timestamp: new Date().toISOString()
  };

  // Add stack in development
  if (process.env.NODE_ENV === 'development') {
    response.stack = err.stack;
    response.details = err.details;
  }

  // Validation errors
  if (err.name === 'ValidationError') {
    response.code = 'VALIDATION_ERROR';
    response.errors = Object.values(err.errors).map(e => ({
      field: e.path,
      message: e.message
    }));
  }

  // JWT errors
  if (err.name === 'JsonWebTokenError') {
    response.code = 'INVALID_TOKEN';
    response.message = 'Invalid authentication token';
  }

  if (err.name === 'TokenExpiredError') {
    response.code = 'TOKEN_EXPIRED';
    response.message = 'Authentication token expired';
  }

  // Database errors
  if (err.code === '23505') { // PostgreSQL unique violation
    response.code = 'DUPLICATE_ERROR';
    response.message = 'Duplicate entry detected';
  }

  res.status(statusCode).json(response);
};

module.exports = { AppError, errorHandler };

// user.service.js
class UserService {
  async getUsers({ page = 1, limit = 10, search = '', sort = 'createdAt', order = 'desc' }) {
    const offset = (page - 1) * limit;

    // Build query
    let query = 'SELECT id, name, email, createdAt FROM users';
    const params = [];

    if (search) {
      query += ' WHERE name ILIKE $1 OR email ILIKE $1';
      params.push(`%${search}%`);
    }

    query += ` ORDER BY ${sort} ${order}`;
    query += ` LIMIT $${params.length + 1} OFFSET $${params.length + 2}`;
    params.push(limit, offset);

    // Count query
    let countQuery = 'SELECT COUNT(*) FROM users';
    const countParams = [];
    if (search) {
      countQuery += ' WHERE name ILIKE $1 OR email ILIKE $1';
      countParams.push(`%${search}%`);
    }

    const [usersResult, countResult] = await Promise.all([
      pool.query(query, params),
      pool.query(countQuery, countParams)
    ]);

    const total = parseInt(countResult.rows[0].count);
    const totalPages = Math.ceil(total / limit);

    return {
      data: usersResult.rows,
      pagination: {
        page: parseInt(page),
        limit: parseInt(limit),
        total,
        totalPages,
        hasNext: page < totalPages,
        hasPrevious: page > 1
      }
    };
  }
}

// user.controller.js
class UserController {
  async getUsers(req, res, next) {
    try {
      const result = await userService.getUsers(req.query);

      // Build links
      const baseUrl = `${req.protocol}://${req.get('host')}${req.path}`;
      const links = {
        self: `${baseUrl}?page=${result.pagination.page}&limit=${result.pagination.limit}`
      };

      if (result.pagination.hasNext) {
        links.next = `${baseUrl}?page=${result.pagination.page + 1}&limit=${result.pagination.limit}`;
      }

      if (result.pagination.hasPrevious) {
        links.prev = `${baseUrl}?page=${result.pagination.page - 1}&limit=${result.pagination.limit}`;
      }

      res.json({
        data: result.data,
        pagination: result.pagination,
        links
      });
    } catch (err) {
      next(err);
    }
  }
}

// external.controller.js
const axios = require('axios');
const { AppError } = require('../middleware/error.middleware');

class ExternalController {
  async getCombinedData(req, res, next) {
    try {
      // Call multiple external APIs concurrently
      const [users, posts, comments] = await Promise.all([
        axios.get('https://jsonplaceholder.typicode.com/users'),
        axios.get('https://jsonplaceholder.typicode.com/posts'),
        axios.get('https://jsonplaceholder.typicode.com/comments')
      ]);

      res.json({
        users: users.data.slice(0, 5),
        posts: posts.data.slice(0, 5),
        comments: comments.data.slice(0, 5),
        meta: {
          totalUsers: users.data.length,
          totalPosts: posts.data.length,
          totalComments: comments.data.length
        }
      });
    } catch (err) {
      next(err);
    }
  }

  async getDataWithFallback(req, res, next) {
    try {
      // Use allSettled to handle partial failures
      const results = await Promise.allSettled([
        axios.get('https://api1.example.com/data'),
        axios.get('https://api2.example.com/data'),
        axios.get('https://api3.example.com/data')
      ]);

      const response = {
        data: [],
        failures: []
      };

      results.forEach((result, index) => {
        if (result.status === 'fulfilled') {
          response.data.push(result.value.data);
        } else {
          response.failures.push({
            source: `API ${index + 1}`,
            error: result.reason.message
          });
        }
      });

      // If all fail, return error
      if (response.data.length === 0) {
        throw new AppError('All external services unavailable', 503);
      }

      res.json(response);
    } catch (err) {
      next(err);
    }
  }

  async getDataWithTimeout(req, res, next) {
    try {
      const timeout = 5000;

      const results = await Promise.race([
        Promise.all([
          axios.get('https://api1.example.com/data'),
          axios.get('https://api2.example.com/data')
        ]),
        new Promise((_, reject) => 
          setTimeout(() => reject(new Error('Request timeout')), timeout)
        )
      ]);

      res.json(results);
    } catch (err) {
      next(err);
    }
  }
}
